create or replace function public.simulate_pvp_battle(a jsonb,d jsonb,seed text) returns jsonb language plpgsql security definer set search_path=public as $$declare ast jsonb;dst jsonb;initiative jsonb;entry jsonb;actor jsonb;target jsonb;side text;target_id text;log jsonb:='[]';raw numeric;reduction numeric;variance numeric;damage int;new_hp int;turn int:=0;last_turn int:=0;winner text;alive_a boolean;alive_d boolean;hp_a numeric;hp_d numeric;begin select coalesce(jsonb_agg(x||jsonb_build_object('currentHp',(x->>'finalHp')::int)),'[]')into ast from jsonb_array_elements(a)x;select coalesce(jsonb_agg(x||jsonb_build_object('currentHp',(x->>'finalHp')::int)),'[]')into dst from jsonb_array_elements(d)x;select jsonb_agg(jsonb_build_object('side',q.side,'heroId',q.hero_id)order by q.speed desc,q.level desc,q.tie)into initiative from(select'attacker'side,x->>'heroId'hero_id,coalesce((x->>'speed')::int,(x->>'level')::int)speed,(x->>'level')::int level,hashtextextended(seed||(x->>'heroId'),0)tie from jsonb_array_elements(a)x union all select'defender',x->>'heroId',coalesce((x->>'speed')::int,(x->>'level')::int),(x->>'level')::int,hashtextextended(seed||(x->>'heroId'),0)from jsonb_array_elements(d)x)q;if initiative is null or jsonb_array_length(initiative)=0 then return jsonb_build_object('attackerState',ast,'defenderState',dst,'battleLog',log,'winnerSide','defender','turns',1,'totalTurns',1);end if;for turn in 1..50 loop entry:=initiative->((turn-1)%jsonb_array_length(initiative));side:=entry->>'side';actor:=null;target:=null;if side='attacker'then select x into actor from jsonb_array_elements(ast)x where x->>'heroId'=entry->>'heroId'and(x->>'currentHp')::int>0;select x into target from jsonb_array_elements(dst)x where(x->>'currentHp')::int>0 order by(x->>'currentHp')::numeric/greatest(1,(x->>'finalHp')::numeric),hashtextextended(seed||turn::text||(x->>'heroId'),0)limit 1;else select x into actor from jsonb_array_elements(dst)x where x->>'heroId'=entry->>'heroId'and(x->>'currentHp')::int>0;select x into target from jsonb_array_elements(ast)x where(x->>'currentHp')::int>0 order by(x->>'currentHp')::numeric/greatest(1,(x->>'finalHp')::numeric),hashtextextended(seed||turn::text||(x->>'heroId'),0)limit 1;end if;if actor is null or target is null then continue;end if;last_turn:=turn;raw:=(actor->>'finalAtk')::numeric;reduction:=coalesce((target->>'defense')::numeric,0)/(coalesce((target->>'defense')::numeric,0)+300);variance:=.95+pvp_stat_unit(seed||':'||turn||':damage')*.10;damage:=greatest(1,round(raw*(1-reduction)*variance));new_hp:=greatest(0,(target->>'currentHp')::int-damage);target_id:=target->>'heroId';if side='attacker'then select jsonb_agg(case when x->>'heroId'=target_id then x||jsonb_build_object('currentHp',new_hp)else x end)into dst from jsonb_array_elements(dst)x;else select jsonb_agg(case when x->>'heroId'=target_id then x||jsonb_build_object('currentHp',new_hp)else x end)into ast from jsonb_array_elements(ast)x;end if;log:=log||jsonb_build_array(jsonb_build_object('turn',turn,'side',side,'attackerId',actor->>'heroId','targetId',target_id,'damage',damage,'remainingHp',new_hp));select exists(select 1 from jsonb_array_elements(ast)x where(x->>'currentHp')::int>0),exists(select 1 from jsonb_array_elements(dst)x where(x->>'currentHp')::int>0)into alive_a,alive_d;if not alive_d then winner:='attacker';exit;elsif not alive_a then winner:='defender';exit;end if;end loop;if winner is null then select coalesce(sum((x->>'currentHp')::numeric/greatest(1,(x->>'finalHp')::numeric)),0)into hp_a from jsonb_array_elements(ast)x;select coalesce(sum((x->>'currentHp')::numeric/greatest(1,(x->>'finalHp')::numeric)),0)into hp_d from jsonb_array_elements(dst)x;winner:=case when hp_a>hp_d then'attacker'else'defender'end;end if;return jsonb_build_object('attackerState',ast,'defenderState',dst,'battleLog',log,'winnerSide',winner,'turns',greatest(1,least(50,last_turn)),'totalTurns',greatest(1,least(50,last_turn)));end$$;